begin;
create extension if not exists pgtap with schema extensions;
select plan(30);
insert into auth.users(id,email,email_confirmed_at,encrypted_password) values
('f1100000-0000-4000-8000-000000000001','platform-invite@example.test',now(),'synthetic'),
('f1100000-0000-4000-8000-000000000002','target-invite@example.test',now(),'synthetic'),
('f1100000-0000-4000-8000-000000000003','other-invite@example.test',now(),'synthetic');
insert into public.profiles(id,display_name) select id,'QA invitación' from auth.users where id in ('f1100000-0000-4000-8000-000000000001','f1100000-0000-4000-8000-000000000002','f1100000-0000-4000-8000-000000000003');
insert into public.platform_admins(user_id) values ('f1100000-0000-4000-8000-000000000001');
insert into public.agencies(id,name,slug,ars_per_usd) values ('f2200000-0000-4000-8000-000000000001','QA invitación','qa-invite-db',1000);
set local role anon;
select throws_ok($$select public.begin_superadmin_invitation('f2200000-0000-4000-8000-000000000001','target-invite@example.test','QA')$$,'42501',null,'Anonymous cannot invite');
set local role authenticated;
select set_config('request.jwt.claims','{"sub":"f1100000-0000-4000-8000-000000000003","role":"authenticated","user_metadata":{"role":"platform_admin"}}',true);
select throws_ok($$select public.begin_superadmin_invitation('f2200000-0000-4000-8000-000000000001','target-invite@example.test','QA')$$,'42501',null,'Metadata cannot grant invitation authority');
select set_config('request.jwt.claims','{"sub":"f1100000-0000-4000-8000-000000000001","role":"authenticated"}',true);
select lives_ok($$select public.begin_superadmin_invitation('f2200000-0000-4000-8000-000000000001','target-invite@example.test','QA')$$,'Platform reserves invitation');
select set_config('test.invitation_id',(select id::text from public.agency_invitations where agency_id='f2200000-0000-4000-8000-000000000001'),true);
select is((select count(*) from public.memberships where agency_id='f2200000-0000-4000-8000-000000000001'),0::bigint,'Sending grants no membership');
select throws_ok($$select public.begin_superadmin_invitation('f2200000-0000-4000-8000-000000000001','other-invite@example.test','QA')$$,'P0001',null,'Pending invitation reserves initial slot');
select throws_ok($$select public.assign_initial_agency_superadmin('f2200000-0000-4000-8000-000000000001','f1100000-0000-4000-8000-000000000003')$$,'P0001',null,'Existing-profile assignment respects invitation reservation');
select throws_ok($$select public.finish_superadmin_invitation((select id from public.agency_invitations limit 1),'f1100000-0000-4000-8000-000000000002',true)$$,'42501',null,'Caller cannot forge delivery or target');
select throws_ok($$select public.prepare_existing_invitation_profile(current_setting('test.invitation_id')::uuid)$$,'42501',null,'Caller cannot resolve Auth users through the service-only adapter');
reset role;
select is(public.prepare_existing_invitation_profile(current_setting('test.invitation_id')::uuid),'f1100000-0000-4000-8000-000000000002'::uuid,'Trusted adapter can prepare the confirmed existing account');
select is((select display_name from public.profiles where id='f1100000-0000-4000-8000-000000000002'),'QA invitación','Existing display name is preserved');
-- Simulate only the trusted mail adapter binding its verified Auth response.
update auth.users set invited_at=now() where id='f1100000-0000-4000-8000-000000000002';
select throws_ok($$select public.finish_superadmin_invitation(current_setting('test.invitation_id')::uuid,'f1100000-0000-4000-8000-000000000003',true)$$,'42501',null,'Trusted binding still checks the Auth email and invited identity');
select public.finish_superadmin_invitation((select id from public.agency_invitations where agency_id='f2200000-0000-4000-8000-000000000001'),'f1100000-0000-4000-8000-000000000002',true);
set local role authenticated;
select set_config('request.jwt.claims','{"sub":"f1100000-0000-4000-8000-000000000003","role":"authenticated"}',true);
select throws_ok($$select public.accept_superadmin_invitation(current_setting('test.invitation_id')::uuid)$$,'42501',null,'Another identity cannot redeem a known invitation ID');
select is((select count(*) from public.agency_invitations),0::bigint,'Other identities cannot read invitations');
select throws_ok($$update public.agency_invitations set status='accepted'$$,'42501',null,'Clients cannot forge invitation state');
select throws_ok($$select private.create_initial_superadmin('f2200000-0000-4000-8000-000000000001','f1100000-0000-4000-8000-000000000003',auth.uid())$$,'42501',null,'Private mutation core cannot be invoked by clients');
reset role;
update public.agency_invitations set expires_at=now()-interval '1 second' where id=current_setting('test.invitation_id')::uuid;
set local role authenticated;
select set_config('request.jwt.claims','{"sub":"f1100000-0000-4000-8000-000000000002","role":"authenticated"}',true);
select throws_ok($$select public.accept_superadmin_invitation(current_setting('test.invitation_id')::uuid)$$,'P0001',null,'Expired invitation cannot grant access');
reset role;
update public.agency_invitations set expires_at=now()+interval '1 hour' where id=current_setting('test.invitation_id')::uuid;
update public.platform_admins set is_active=false where user_id='f1100000-0000-4000-8000-000000000001';
set local role authenticated;
select throws_ok($$select public.accept_superadmin_invitation(current_setting('test.invitation_id')::uuid)$$,'42501',null,'Revoked inviter cannot grant access later');
reset role;
update public.platform_admins set is_active=true where user_id='f1100000-0000-4000-8000-000000000001';
update auth.users set encrypted_password='' where id='f1100000-0000-4000-8000-000000000002';
set local role authenticated;
select throws_ok($$select public.accept_superadmin_invitation(current_setting('test.invitation_id')::uuid)$$,'42501',null,'Verified email alone without a password is insufficient');
reset role;
update auth.users set encrypted_password='synthetic',email='changed-invite@example.test' where id='f1100000-0000-4000-8000-000000000002';
set local role authenticated;
select throws_ok($$select public.accept_superadmin_invitation(current_setting('test.invitation_id')::uuid)$$,'42501',null,'Changed email cannot claim the original invitation');
reset role;
update auth.users set email='target-invite@example.test' where id='f1100000-0000-4000-8000-000000000002';
create function pg_temp.reject_invite_acceptance_audit() returns trigger language plpgsql as $$
begin
 if new.action='invitation.accepted' then raise exception 'Synthetic audit failure' using errcode='22000'; end if;
 return new;
end; $$;
create trigger reject_invite_acceptance_audit before insert on public.audit_events for each row execute function pg_temp.reject_invite_acceptance_audit();
set local role authenticated;
select throws_ok($$select public.accept_superadmin_invitation(current_setting('test.invitation_id')::uuid)$$,'22000',null,'Audit failure rejects acceptance');
select is((select private.current_agency_role('f2200000-0000-4000-8000-000000000001')),null,'Audit failure leaves no membership');
select is((select status from public.agency_invitations where id=current_setting('test.invitation_id')::uuid),'sent','Audit failure preserves resumable state');
reset role;
drop trigger reject_invite_acceptance_audit on public.audit_events;
set local role authenticated;
select set_config('request.jwt.claims','{"sub":"f1100000-0000-4000-8000-000000000002","role":"authenticated"}',true);
select lives_ok($$select public.accept_superadmin_invitation((select id from public.agency_invitations limit 1))$$,'Bound verified identity accepts');
select is((select private.current_agency_role('f2200000-0000-4000-8000-000000000001')),'agency_superadmin','Acceptance grants actual agency access');
select throws_ok($$select public.accept_superadmin_invitation((select id from public.agency_invitations limit 1))$$,'P0001',null,'Invitation cannot be accepted twice');
select set_config('request.jwt.claims','{"sub":"f1100000-0000-4000-8000-000000000001","role":"authenticated"}',true);
select is((select status from public.agency_invitations where agency_id='f2200000-0000-4000-8000-000000000001'),'accepted','Acceptance persisted');
select is((select count(*) from public.audit_events where agency_id='f2200000-0000-4000-8000-000000000001'),3::bigint,'Sent, membership and acceptance audited');
reset role;
insert into public.agencies(id,name,slug,ars_per_usd) values ('f2200000-0000-4000-8000-000000000002','QA cancelación','qa-invite-cancel-db',1000);
set local role authenticated;
select public.begin_superadmin_invitation('f2200000-0000-4000-8000-000000000002','cancel-invite@example.test','QA');
select lives_ok($$select public.cancel_superadmin_invitation((select id from public.agency_invitations where agency_id='f2200000-0000-4000-8000-000000000002'))$$,'Platform cancels sending invitation');
reset role;
select throws_ok($$select public.finish_superadmin_invitation((select id from public.agency_invitations where agency_id='f2200000-0000-4000-8000-000000000002'),'f1100000-0000-4000-8000-000000000002',true)$$,'P0001',null,'Late mail callback cannot revive cancelled invitation');
select is((select status from public.agency_invitations where agency_id='f2200000-0000-4000-8000-000000000002'),'cancelled','Cancelled state is retained');
select * from finish();
rollback;
